function OperationsCenter({data}:any){const o=data?.operations||{};const stores=Array.isArray(data?.recentTenants)?data.recentTenants:[];return <div className="sa-operations-page"><div className="panel sa-page-head"><div><h2>Operasyon Merkezi</h2><p className="muted">Platform sağlığını ve mağaza bazlı operasyon sinyallerini Super Admin üzerinden yönetin.</p></div><select className="sa-store-filter" defaultValue="all"><option value="all">Tüm mağazalar</option>{stores.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></div><div className="cards">{[['API',o.api||'OK'],['Veritabanı',o.database||'OK'],['Kargo hatası',o.shippingErrors||0],['ERP hatası',o.erpFailures||0],['Mesaj hatası',o.messageFailures||0],['Pasif mağaza',o.inactiveTenants||0]].map(([k,v])=><div className="card" key={String(k)}><div className="muted">{k}</div><div className="metric">{v}</div></div>)}</div><div className="panel"><div className="toolbar"><div><h3>Dikkat gerektiren mağazalar</h3><p className="muted">Destek ve operasyon sinyalleri mağaza bağlamında incelenir.</p></div></div><div className="table-scroll"><table><thead><tr><th>Mağaza</th><th>Ürün</th><th>Sipariş</th><th>Müşteri</th><th>Durum</th></tr></thead><tbody>{stores.map((x:any)=><tr key={x.id}><td><b>{x.name}</b><div className="muted">{x.slug||x.publicSlug||''}</div></td><td>{x._count?.products||0}</td><td>{x._count?.orders||0}</td><td>{x._count?.customers||0}</td><td><span className="pill">{x.status||'—'}</span></td></tr>)}</tbody></table></div></div><div className="panel"><h3>Son destek / operasyon kayıtları</h3><div className="sa-ops-list">{(o.recentTickets||[]).map((x:any)=><div key={x.id}><b>{x.subject}</b><span>{x.tenant?.name||'-'} · {x.priority} · {x.status}</span></div>)}{!(o.recentTickets||[]).length&&<div className="muted">Aktif operasyon uyarısı yok.</div>}</div></div></div>}

