  const rows=Array.isArray(data?.[key])?data[key]:[];const locales=Array.isArray(data?.locales)?data.locales:[];
  const[editing,setEditing]=useState<any>(null),[busy,setBusy]=useState(false),[err,setErr]=useState('');
  const labels:any={contracts:{title:t('contracts'),help:t('contractsHelp')},blog:{title:t('blog'),help:t('blogHelp')},pages:{title:t('pages'),help:t('pagesHelp')}};
