  return <><div className="panel sa-page-head"><div><h3>{labels[key].title}</h3><p className="muted">{labels[key].help}</p></div><button className="btn" onClick={newRow}>{t('newAdd')}</button></div>{err&&<div className="error">{err}</div>}<div className="panel"><Table rows={rows} cols={[["slug",t('slug')],["status",t('status')],["isActive",t('active')],["updatedAt",t('date')]]}/>{rows.map((x:any)=><button key={x.id} className="btn secondary sa-inline-edit" onClick={()=>setEditing(x)}>{t('edit')} · {displayTranslation(x.translations,locales,'name',x.slug||x.id)}</button>)}</div>{editing&&<ContentModal kind={key} row={editing} locales={locales} busy={busy} onClose={()=>setEditing(null)} onSave={(row:any)=>saveRows([...rows.filter((x:any)=>x.id!==row.id),row])}/>}</>
