function ContentModal({kind,row,locales,busy,onClose,onSave}:any){const {t}=useUiI18n(UI as any);const[form,setForm]=useState<any>({...row,translations:row.translations||{},modules:Array.isArray(row.modules)?row.modules:[]}),[err,setErr]=useState('');const[modulesText,setModulesText]=useState(JSON.stringify(Array.isArray(row.modules)?row.modules:[],null,2));function save(){if(kind==='pages'){try{const parsed=JSON.parse(modulesText||'[]');if(!Array.isArray(parsed))throw new Error();form.modules=parsed}catch{setErr(t('moduleJsonError'));return}}onSave({...form,updatedAt:new Date().toISOString(),createdAt:form.createdAt||new Date().toISOString()})}return <Modal title={kind==='contracts'?t('contracts'):kind==='blog'?t('blog'):t('pages')} onClose={onClose} wide>{err&&<div className="error">{err}</div>}<div className="form-grid"><label>{t('slug')}<input value={form.slug||''} onChange={e=>setForm({...form,slug:e.target.value})}/></label><label>{t('status')}<select value={form.status||'DRAFT'} onChange={e=>setForm({...form,status:e.target.value})}><option value="DRAFT">{t('draft')}</option><option value="PUBLISHED">{t('published')}</option></select></label><label>{t('active')}<select value={String(form.isActive!==false)} onChange={e=>setForm({...form,isActive:e.target.value==='true'})}><option value="true">{t('active')}</option><option value="false">{t('inactiveLabel')}</option></select></label><div/><div className="full"><TranslationEditor locales={locales} value={form.translations} onChange={(v:any)=>setForm({...form,translations:v})} fields={['name','summary','description']}/></div>{kind==='pages'&&<label className="full">{t('modules')}<textarea className="sa-json-editor" value={modulesText} onChange={e=>setModulesText(e.target.value)}/></label>}</div><ModalActions onClose={onClose} onSave={save} busy={busy}/></Modal>}

function TranslationEditor({locales,value,onChange,fields=['name','description']}:any){const {t}=useUiI18n(UI as any);const rows=Array.isArray(locales)&&locales.length?locales:[{locale:'tr',label:'Türkçe'}];const[active,setActive]=useState(String(rows[0].locale));useEffect(()=>{if(!rows.some((x:any)=>String(x.locale)===active))setActive(String(rows[0].locale))},[locales]);const row=value?.[active]||{};const set=(k:string,v:string)=>onChange({...value,[active]:{...row,[k]:v}});return <div className="sa-translation-editor"><div className="sa-language-tabs">{rows.map((l:any)=><button type="button" key={l.locale} className={active===String(l.locale)?'active':''} onClick={()=>setActive(String(l.locale))}>{l.label||l.locale}</button>)}</div>{fields.includes('name')&&<label>{t('title')}<input value={row.name||''} onChange={e=>set('name',e.target.value)}/></label>}{fields.includes('summary')&&<label>{t('summary')}<textarea rows={2} value={row.summary||''} onChange={e=>set('summary',e.target.value)}/></label>}{fields.includes('description')&&<label>{t('description')}<textarea rows={4} value={row.description||''} onChange={e=>set('description',e.target.value)}/></label>}</div>}
