function categoryLabel(categories:any[],id:any,locales:any[]){if(!id)return 'Kategorisiz';const row=(categories||[]).find((x:any)=>String(x.id)===String(id));if(!row)return String(id);return displayTranslation(row.translations,locales,'name',row.name||row.id||id)}
function MediaChooser({req,selected,onChange,multiple=false,label=saText('media.choose')}:any){
  const[busy,setBusy]=useState(false),[open,setOpen]=useState(false),[rows,setRows]=useState<any[]>([]),[loading,setLoading]=useState(false),[err,setErr]=useState('');
  async function load(){setLoading(true);setErr('');try{const x=await req('/superadmin/media');setRows(Array.isArray(x)?x:[])}catch(e:any){setErr(e.message||saText('media.loadFailed'))}finally{setLoading(false)}}
  async function upload(file:File){setBusy(true);setErr('');try{const dataBase64=await fileToData(file);const row=await req('/superadmin/media/upload',{method:'POST',body:JSON.stringify({fileName:file.name,mimeType:file.type,dataBase64})});setRows(x=>[row,...x.filter((r:any)=>r.publicUrl!==row.publicUrl)]);choose(row.publicUrl)}catch(e:any){setErr(e.message||saText('media.uploadFailed'))}finally{setBusy(false)}}
  function choose(url:string){if(multiple)onChange(Array.from(new Set([...(Array.isArray(selected)?selected:[]),url])));else{onChange(url);setOpen(false)}}
  function remove(url:string){if(multiple)onChange((Array.isArray(selected)?selected:[]).filter((x:string)=>x!==url));else onChange('')}
  async function show(){setOpen(true);await load()}
  return <div className="sa-inline-upload"><div className="sa-media-actions"><button type="button" className="btn secondary" onClick={()=>void show()}>{label}</button><label className="btn secondary">{busy?saText('deep.final3.004'):saText('deep.final3.005')}<input hidden type="file" accept="image/jpeg,image/png,image/webp,image/avif,image/svg+xml" onChange={e=>{const f=e.target.files?.[0];if(f)void upload(f);e.currentTarget.value=''}}/></label></div>{multiple?<div className="sa-shot-list">{(Array.isArray(selected)?selected:[]).map((u:string)=><button type="button" key={u} onClick={()=>remove(u)}><img src={u} alt=""/><span>×</span></button>)}</div>:selected&&<div className="sa-selected-media"><img className="sa-preview-image" src={selected} alt=""/><button type="button" className="btn secondary" onClick={()=>remove(String(selected))}>{saText('deep.final3.006')}</button></div>}{open&&<div className="sa-media-modal-backdrop" onMouseDown={e=>{if(e.currentTarget===e.target)setOpen(false)}}><div className="sa-media-modal"><div className="sa-modal-head"><div><h2>Medya Galerisi</h2><p className="muted">{saText('deep.final3.007')}</p></div><button type="button" className="btn secondary" onClick={()=>setOpen(false)}>Kapat</button></div><div className="sa-media-toolbar"><label className="btn">{busy?saText('deep.final3.004'):saText('deep.final3.008')}<input hidden type="file" accept="image/jpeg,image/png,image/webp,image/avif,image/svg+xml" onChange={e=>{const f=e.target.files?.[0];if(f)void upload(f);e.currentTarget.value=''}}/></label><button type="button" className="btn secondary" disabled={loading} onClick={()=>void load()}>Yenile</button></div>{err&&<div className="error">{err}</div>}{loading?<div className="sa-empty-state">{saText('deep.final3.009')}</div>:<div className="sa-media-grid">{rows.map((r:any)=>{const active=multiple?(Array.isArray(selected)&&selected.includes(r.publicUrl)):selected===r.publicUrl;return <button type="button" key={r.id||r.publicUrl} className={'sa-media-item '+(active?'active':'')} onClick={()=>choose(r.publicUrl)}><img src={r.publicUrl} alt={r.alt||r.originalName||''}/><span>{r.originalName||r.fileName||'Görsel'}</span>{active&&<b>{saText('deep.final3.010')}</b>}</button>})}{!rows.length&&<div className="sa-empty-state">{saText('deep.final3.011')}</div>}</div>}</div></div>}</div>
}

function PricingMatrix({plans,value,onChange,withTrial=false,currencies=[]}:any){const rows=Array.isArray(value)?value:[];const currencies2=currencies.length?currencies:[{code:'TRY'}];const def=currencies2.find((x:any)=>x.isDefault)?.code||currencies2[0]?.code||'TRY';function current(id:string){return rows.find((x:any)=>String(x.planId)===String(id))||{planId:id,enabled:false,included:false,price:null,currency:def,trialDays:0}}function patch(id:string,k:string,v:any){const c=current(id);onChange([...rows.filter((x:any)=>String(x.planId)!==String(id)),{...c,[k]:v}])}return <div className="sa-pricing-matrix">{(plans||[]).map((p:any)=>{const c=current(p.id);const exists=rows.some((x:any)=>String(x.planId)===String(p.id));const enabled=exists&&c.enabled!==false;return <div className={'sa-price-row '+(enabled?'enabled':'')} key={p.id}><label className="sa-plan-check"><input type="checkbox" checked={enabled} onChange={e=>patch(p.id,'enabled',e.target.checked)}/><span><b>{p.name}</b><small>{p.code}</small></span></label><div className="sa-price-fields">{enabled&&<><label>{saText('deep.final3.012')}<select value={c.included?'included':'paid'} onChange={e=>patch(p.id,'included',e.target.value==='included')}><option value="included">Pakete dahil</option><option value="paid">{saText('deep.final3.013')}</option></select></label>{!c.included&&<><label>Fiyat<input type="number" min="0" step="0.01" value={c.price??''} onChange={e=>patch(p.id,'price',e.target.value===''?null:Number(e.target.value))}/></label><label>Para birimi<select value={c.currency||def} onChange={e=>patch(p.id,'currency',e.target.value)}>{currencies2.map((x:any)=><option value={x.code} key={x.code}>{x.code}{x.symbol?` · ${x.symbol}`:''}</option>)}</select></label></>}{withTrial&&<label>{saText('deep.final3.014')}<input type="number" min="0" value={c.trialDays||0} onChange={e=>patch(p.id,'trialDays',Math.max(0,Number(e.target.value||0)))}/></label>}</>}</div></div>})}</div>}
function PackageSummary({plans,pricing}:any){const rows=(pricing||[]).filter((x:any)=>x.enabled!==false);if(!rows.length)return <span className="muted">{saText('deep.final3.015')}</span>;return <div className="sa-package-summary">{rows.map((r:any)=>{const p=(plans||[]).find((x:any)=>String(x.id)===String(r.planId));return <span key={r.planId}>{p?.name||r.planId}{r.included?' · dahil':r.price!==null&&r.price!==undefined?` · ${r.price} ${r.currency||'TRY'}`:''}</span>})}</div>}

