  return <>{err&&<div className="error">{err}</div>}<div className="panel sa-page-head"><div><h2>Paketler</h2><p className="muted">Frontend paket kartları, kayıt akışı ve mağaza limitlerini tek yerden yönetin. Fiyatlandırma yıllık gösterilir.</p></div><button className="btn" onClick={()=>setEditing({})}>Paket ekle</button></div><div className="panel"><div className="table-scroll"><table><thead><tr><th>Paket</th><th>Kod</th><th>Yıllık fiyat</th><th>Personel</th><th>Ürün</th><th>Sipariş / ay</th><th>Frontend</th><th>Durum</th><th></th></tr></thead><tbody>{plans.map((p:any)=>{const m=p.features?.marketing||{};const name=m.translations?.[def]?.name||p.name;return <tr key={p.id}><td><b>{name}</b>{m.translations?.[def]?.badge&&<div className="muted">{m.translations[def].badge}</div>}</td><td>{p.code}</td><td>{p.yearlyPrice!==null&&p.yearlyPrice!==undefined?Number(p.yearlyPrice).toLocaleString('tr-TR')+' '+p.currency:'-'}</td><td>{p.maxStaff}</td><td>{p.maxProducts}</td><td>{p.maxOrdersPerMonth??'Sınırsız'}</td><td>{m.visibleOnLanding!==false?'Göster':'Gizli'}</td><td><span className={'sa-status '+(p.isActive?'active':'inactive')}>{p.isActive?'Aktif':'Pasif'}</span></td><td><button className="btn secondary" onClick={()=>setEditing(p)}>Düzenle</button></td></tr>})}</tbody></table></div></div>{editing&&<PlanModal plan={editing} locales={locales} req={req} onClose={()=>setEditing(null)} onSaved={async()=>{setEditing(null);await reload()}}/>}</>
