  async function save(){setBusy(true);setErr('');try{if(form.yearlyPrice==='')throw new Error('Yıllık fiyat zorunludur.');const defaultTranslation=form.marketing?.translations?.[defaultLocale]||{};const features={...(form.features||{}),marketing:form.marketing};const payload={name:String(defaultTranslation.name||form.name||form.code).trim(),code:String(form.code||'').trim().toUpperCase(),description:String(defaultTranslation.summary||form.description||'').trim(),monthlyPrice:Number(form.monthlyPrice||0),yearlyPrice:Number(form.yearlyPrice),currency:String(form.currency||'TRY').toUpperCase(),trialDays:Number(form.trialDays||0),maxStaff:Number(form.maxStaff||1),maxProducts:Number(form.maxProducts||1),maxOrdersPerMonth:form.maxOrdersPerMonth===''?null:Number(form.maxOrdersPerMonth),isActive:!!form.isActive,sortOrder:Number(form.sortOrder||0),features};await req(isNew?'/superadmin/plans':'/superadmin/plans/'+plan.id,{method:isNew?'POST':'PATCH',body:JSON.stringify(payload)});onSaved()}catch(e:any){setErr(e.message)}finally{setBusy(false)}}
