function AppControl({workspace,req,reload}:any){const apps=Array.isArray(workspace?.items)?workspace.items:[];const plans=Array.isArray(workspace?.plans)?workspace.plans:[];const locales=Array.isArray(workspace?.locales)&&workspace.locales.length?workspace.locales:[{locale:'tr',label:'Türkçe'}];const currencies=Array.isArray(workspace?.currencies)?workspace.currencies:[];const categories=Array.isArray(workspace?.categories)?workspace.categories:[];const[section,setSection]=useState<'apps'|'categories'>('apps'),[editing,setEditing]=useState<any>(null),[uploading,setUploading]=useState(false),[uploadError,setUploadError]=useState('');const uploadRef=useRef<HTMLInputElement|null>(null);async function uploadModule(file?:File){if(!file)return;setUploading(true);setUploadError('');try{const fd=new FormData();fd.append('file',file);await req('/superadmin/apps/import-package',{method:'POST',body:fd});await reload()}catch(e:any){setUploadError(e.message||'Modül yüklenemedi')}finally{setUploading(false);if(uploadRef.current)uploadRef.current.value=''}}return <div><div className="panel sa-page-head"><div><h2>Uygulamalar</h2><p className="muted">ZIP modüllerini güvenli paket olarak yükleyin; çalıştırılabilir kod kabul edilmez.</p>{uploadError&&<div className="error">{uploadError}</div>}</div><div className="row"><input ref={uploadRef} type="file" accept=".zip,application/zip" hidden onChange={e=>void uploadModule(e.target.files?.[0])}/><button className="btn secondary" disabled={uploading} onClick={()=>uploadRef.current?.click()}>{uploading?'Yükleniyor…':'ZIP modül yükle'}</button><button className="btn" onClick={()=>setEditing({})}>Uygulama ekle</button></div></div><div className="sa-catalog-tabs"><button className={section==='apps'?'active':''} onClick={()=>setSection('apps')}>Uygulamalar</button><button className={section==='categories'?'active':''} onClick={()=>setSection('categories')}>Kategoriler</button></div>{section==='categories'?<AppCategories rows={categories} locales={locales} req={req} onSaved={reload}/>:<div className="panel"><div className="table-scroll"><table><thead><tr><th>Uygulama</th><th>Kategori</th><th>Paketler</th><th>Kurulum</th><th>Durum</th><th></th></tr></thead><tbody>{apps.map((a:any)=>{const meta=a.settingsSchema?.marketplace||{};return <tr key={a.id}><td><b>{displayTranslation(meta.translations,locales,'name',a.name)}</b><small className="muted dblock">{a.slug}</small></td><td>{categoryLabel(categories,meta.categoryId||a.category,locales)}</td><td><PackageSummary plans={plans} pricing={(a.planPrices||[]).map((x:any)=>({planId:x.planId,enabled:x.isActive!==false,included:x.included,price:x.price,currency:x.currency,trialDays:meta.planTrials?.[x.planId]||0}))}/></td><td>{a._count?.installs||0}</td><td><span className={'sa-status '+(a.isActive?'active':'inactive')}>{a.isActive?'Aktif':'Pasif'}</span></td><td><button className="btn secondary" onClick={()=>setEditing(a)}>{saText('deep.final3.021')}</button></td></tr>})}</tbody></table></div></div>}{editing&&<AppModal app={editing} plans={plans} locales={locales} currencies={currencies} categories={categories} req={req} onClose={()=>setEditing(null)} onSaved={async()=>{setEditing(null);await reload()}}/>}</div>}

