function PlatformProductsControl({data,req,reload}:any){
  const[err,setErr]=useState('');
  const[busy,setBusy]=useState(false);
  async function submitCredit(e:any,kind:'ai'|'email'){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);setErr('');try{await req('/superadmin/products/credits/'+kind,{method:'POST',body:JSON.stringify({name:f.get('name'),code:f.get('code'),credits:Number(f.get('credits')||0),price:Number(f.get('price')||0),currency:'TRY'})});e.currentTarget.reset();await reload()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}
  async function submitCoupon(e:any){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);setErr('');try{await req('/superadmin/products/coupons',{method:'POST',body:JSON.stringify({name:f.get('name'),code:f.get('code'),type:f.get('type'),value:Number(f.get('value')||0),usageLimit:f.get('usageLimit')?Number(f.get('usageLimit')):null,perTenantLimit:f.get('perTenantLimit')?Number(f.get('perTenantLimit')):null,appliesTo:['ALL']})});e.currentTarget.reset();await reload()}catch(x:any){setErr(x.message)}finally{setBusy(false)}}
  return <div>{err&&<div className="alert alert-danger">{err}</div>}
    <div className="panel sa-page-head"><div><h2>Ürünler</h2><p className="muted">Paket, tema, uygulama, AI/e-posta kredisi ve indirim kodlarını tek ürün merkezinden yönetin.</p></div></div>
    <div className="cards"><div className="card"><div className="muted">Paket</div><div className="metric">{data.plans?.length||0}</div></div><div className="card"><div className="muted">Tema</div><div className="metric">{data.themes?.length||0}</div></div><div className="card"><div className="muted">Uygulama</div><div className="metric">{data.apps?.length||0}</div></div><div className="card"><div className="muted">Kredi ürünü</div><div className="metric">{(data.aiCredits?.length||0)+(data.emailCredits?.length||0)}</div></div></div>
    <div className="two"><div className="panel"><h3>AI kredi paketi ekle</h3><form className="form-grid" onSubmit={e=>void submitCredit(e,'ai')}><label>Ad<input name="name" required/></label><label>Kod<input name="code" required/></label><label>Kredi<input name="credits" type="number" min="1" required/></label><label>Fiyat<input name="price" type="number" min="0" step="0.01" required/></label><div className="full"><button className="btn" disabled={busy}>Kaydet</button></div></form></div><div className="panel"><h3>E-posta kredi paketi ekle</h3><form className="form-grid" onSubmit={e=>void submitCredit(e,'email')}><label>Ad<input name="name" required/></label><label>Kod<input name="code" required/></label><label>Kredi<input name="credits" type="number" min="1" required/></label><label>Fiyat<input name="price" type="number" min="0" step="0.01" required/></label><div className="full"><button className="btn" disabled={busy}>Kaydet</button></div></form></div></div>
    <div className="panel"><h3>İndirim kodu ekle</h3><form className="form-grid" onSubmit={e=>void submitCoupon(e)}><label>Ad<input name="name" required/></label><label>Kod<input name="code" required/></label><label>Tip<select name="type"><option value="PERCENTAGE">Yüzde</option><option value="FIXED">Sabit tutar</option></select></label><label>Değer<input name="value" type="number" min="0.01" step="0.01" required/></label><label>Toplam kullanım limiti<input name="usageLimit" type="number" min="1"/></label><label>Mağaza başı limit<input name="perTenantLimit" type="number" min="1"/></label><div className="full"><button className="btn" disabled={busy}>Kod oluştur</button></div></form></div>
    <div className="panel"><h3>AI kredi ürünleri</h3><Table rows={data.aiCredits||[]} cols={[["name","Ad"],["code","Kod"],["credits","Kredi"],["price","Fiyat"],["isActive","Aktif"]]}/><h3 className="mt-4">E-posta kredi ürünleri</h3><Table rows={data.emailCredits||[]} cols={[["name","Ad"],["code","Kod"],["credits","Kredi"],["price","Fiyat"],["isActive","Aktif"]]}/><h3 className="mt-4">İndirim kodları</h3><Table rows={data.coupons||[]} cols={[["name","Ad"],["code","Kod"],["type","Tip"],["value","Değer"],["usageCount","Kullanım"],["isActive","Aktif"]]}/></div>
    <div className="panel"><h3>Paketler</h3><Table rows={data.plans||[]} cols={[["name","Ad"],["code","Kod"],["monthlyPrice","Aylık"],["yearlyPrice","Yıllık"],["isActive","Aktif"]]}/><h3 className="mt-4">Temalar</h3><Table rows={data.themes||[]} cols={[["name","Ad"],["slug","Slug"],["basePrice","Fiyat"],["isActive","Aktif"]]}/><h3 className="mt-4">Uygulamalar</h3><Table rows={data.apps||[]} cols={[["name","Ad"],["slug","Slug"],["basePrice","Fiyat"],["billingType","Faturalama"],["isActive","Aktif"]]}/></div>
  </div>
}

