function MembershipModal({member,plans,meta,req,onClose,onSaved}:any){const[busy,setBusy]=useState(false),[err,setErr]=useState('');async function act(path:string,o:any={}){setBusy(true);setErr('');try{await req(path,o);await onSaved()}catch(e:any){setErr(e.message)}finally{setBusy(false)}}return <Modal title={member.name||member.email} subtitle={member.email} onClose={onClose} wide>{err&&<div className="error">{err}</div>}<div className="sa-member-summary"><div><span>{saText('deep.final3.065')}</span><b>{new Date(member.createdAt).toLocaleString('tr-TR')}</b></div><div><span>{saText('deep.final3.066')}</span><b>{member.stores?.length||0}</b></div></div><div className="sa-store-list">{(member.stores||[]).map((s:any)=><StoreAdminCard key={s.id} store={s} plans={plans} meta={meta} req={req} memberId={member.id} onChanged={onSaved}/>)}</div><div className="sa-danger-zone"><h3>{saText('deep.final3.067')}</h3><button className="btn secondary" disabled={busy} onClick={()=>void act('/superadmin/memberships/'+member.id+'/status',{method:'PATCH',body:JSON.stringify({isActive:member.isActive===false})})}>{member.isActive===false?saText('deep.final3.068'):saText('deep.final3.069')}</button><button className="btn danger" disabled={busy} onClick={()=>{if(confirm(saText('deep.final3.070')))void act('/superadmin/memberships/'+member.id,{method:'DELETE'})}}>{saText('deep.final3.071')}</button></div></Modal>}
