function GeneralSettings({data,req,reload,initialSection='general'}:any){
 const D:any={
 tr:{company:'Firma bilgileri',brandName:'Marka adı',legal:'Yasal ünvan',email:'E-posta',phone:'Telefon',website:'Web sitesi',tax:'Vergi numarası',address:'Adres',branding:'Marka görselleri',brandingHelp:'Admin ve Super Admin genelinde kullanılacak logo ve ikonları merkezi olarak yönetin.',logo:'Logo',icon:'İkon',whiteLogo:'Beyaz logo',whiteIcon:'Beyaz ikon',choose:'Medyadan seç',languages:'Mağazalara açılabilecek diller',languageHelp:'Mağaza Admin’i yalnızca burada aktif edilen dilleri seçebilir.',addLanguage:'Dil ekle',active:'Aktif',default:'Varsayılan',delete:'Sil',currencies:'Mağazalara açılabilecek para birimleri',currencyHelp:'Mağaza Admin’i yalnızca burada aktif edilen para birimlerini ekleyebilir.',addCurrency:'Para birimi ekle',save:'Genel ayarları kaydet',saving:'Kaydediliyor…',saved:'Genel ayarlar kaydedildi.'},
 en:{company:'Company information',brandName:'Brand name',legal:'Legal name',email:'Email',phone:'Phone',website:'Website',tax:'Tax number',address:'Address',branding:'Brand assets',brandingHelp:'Manage the logo and icons used across Admin and Super Admin from one place.',logo:'Logo',icon:'Icon',whiteLogo:'White logo',whiteIcon:'White icon',choose:'Choose from media',languages:'Available store languages',languageHelp:'Store Admin can only select languages enabled here.',addLanguage:'Add language',active:'Active',default:'Default',delete:'Delete',currencies:'Available store currencies',currencyHelp:'Store Admin can only add currencies enabled here.',addCurrency:'Add currency',save:'Save general settings',saving:'Saving…',saved:'General settings saved.'},
 de:{company:'Firmendaten',brandName:'Markenname',legal:'Firmenname',email:'E-Mail',phone:'Telefon',website:'Webseite',tax:'Steuernummer',address:'Adresse',branding:'Markenmedien',brandingHelp:'Logo und Icons für Admin und Super Admin zentral verwalten.',logo:'Logo',icon:'Icon',whiteLogo:'Weißes Logo',whiteIcon:'Weißes Icon',choose:'Aus Medien wählen',languages:'Verfügbare Shop-Sprachen',languageHelp:'Im Shop-Admin können nur hier aktivierte Sprachen gewählt werden.',addLanguage:'Sprache hinzufügen',active:'Aktiv',default:'Standard',delete:'Löschen',currencies:'Verfügbare Shop-Währungen',currencyHelp:'Im Shop-Admin können nur hier aktivierte Währungen hinzugefügt werden.',addCurrency:'Währung hinzufügen',save:'Einstellungen speichern',saving:'Speichern…',saved:'Einstellungen gespeichert.'},
 ru:{company:'Данные компании',brandName:'Название бренда',legal:'Юридическое название',email:'Эл. почта',phone:'Телефон',website:'Сайт',tax:'Налоговый номер',address:'Адрес',branding:'Материалы бренда',brandingHelp:'Централизованно управляйте логотипом и иконками для Admin и Super Admin.',logo:'Логотип',icon:'Иконка',whiteLogo:'Белый логотип',whiteIcon:'Белая иконка',choose:'Выбрать из медиа',languages:'Доступные языки магазинов',languageHelp:'В Admin магазина доступны только включенные здесь языки.',addLanguage:'Добавить язык',active:'Активно',default:'По умолчанию',delete:'Удалить',currencies:'Доступные валюты магазинов',currencyHelp:'В Admin магазина доступны только включенные здесь валюты.',addCurrency:'Добавить валюту',save:'Сохранить настройки',saving:'Сохранение…',saved:'Настройки сохранены.'}}
 const{t}=useUiI18n(D);const[section,setSection]=useState<'general'|'aiImage'>(initialSection);const[company,setCompany]=useState(data.company||{}),[branding,setBranding]=useState(data.branding||{}),[locales,setLocales]=useState<any[]>(data.locales||[]),[currencies,setCurrencies]=useState<any[]>(data.currencies||[]),[aiImage,setAiImage]=useState<any>(data.aiImage||{}),[socialAuth,setSocialAuth]=useState<any>({providers:{google:{enabled:true,clientId:'',clientSecret:''},facebook:{enabled:true,clientId:'',clientSecret:''}}}),[busy,setBusy]=useState(false),[msg,setMsg]=useState(''),[err,setErr]=useState('');
 useEffect(()=>{req('/superadmin/customer-auth').then((x:any)=>setSocialAuth({providers:{google:{...x?.providers?.google,clientSecret:''},facebook:{...x?.providers?.facebook,clientSecret:''}}})).catch(()=>{})},[]);
 useEffect(()=>{setCompany(data.company||{});setBranding(data.branding||{});setLocales(data.locales||[]);setCurrencies(data.currencies||[]);setAiImage(data.aiImage||{})},[data]);
 function upd(setter:any,i:number,k:string,v:any){setter((x:any[])=>x.map((r,j)=>j===i?{...r,[k]:v}:r))}
 async function save(){setBusy(true);setMsg('');setErr('');try{await req('/superadmin/platform-settings',{method:'PATCH',body:JSON.stringify({company,branding,locales,currencies,aiImage})});await req('/superadmin/customer-auth',{method:'PATCH',body:JSON.stringify(socialAuth)});setMsg(t('saved'));await reload()}catch(e:any){setErr(e.message)}finally{setBusy(false)}}
 if(section==='aiImage')return <><div className="panel sa-page-head"><div><h3>{saText('deep.final3.081')}</h3><p className="muted">{saText('deep.final3.082')}</p></div><button className="btn secondary" onClick={()=>setSection('general')}>{saText('deep.final3.083')}</button></div><div className="panel"><div className="form-grid"><label>Servis<select value={aiImage.provider||'openai-compatible'} onChange={e=>setAiImage({...aiImage,provider:e.target.value})}><option value="openai-compatible">OpenAI uyumlu servis</option></select></label><label>API adresi<input value={aiImage.baseUrl||'https://api.openai.com/v1'} onChange={e=>setAiImage({...aiImage,baseUrl:e.target.value})} placeholder="https://api.openai.com/v1"/></label><label>{saText('deep.final3.084')}<input value={aiImage.model||'gpt-image-1'} onChange={e=>setAiImage({...aiImage,model:e.target.value})} placeholder="gpt-image-1"/></label><label>{saText('deep.final3.085')}<input type="password" value={aiImage.apiKey||''} onChange={e=>setAiImage({...aiImage,apiKey:e.target.value})} placeholder={aiImage.apiKeyConfigured?saText('deep.final3.086'):saText('deep.final3.087')}/></label></div><p className="muted mt-3">{saText('deep.final3.088')}</p>{msg&&<div className="success">{msg}</div>}{err&&<div className="error">{err}</div>}<div className="sa-save-row"><button className="btn" disabled={busy} onClick={()=>void save()}>{busy?'Kaydediliyor…':saText('deep.final3.089')}</button></div></div></>;
 return <><div className="panel"><div className="toolbar"><h3>Genel Ayarlar</h3><button className="btn secondary" onClick={()=>setSection('aiImage')}>{saText('deep.final3.090')}<Icon icon="iconoir:arrow-right"/></button></div></div><div className="panel"><h3>{t('company')}</h3><div className="form-grid"><label>{t('brandName')}<input value={company.name||''} onChange={e=>setCompany({...company,name:e.target.value})}/></label><label>{t('legal')}<input value={company.legalName||''} onChange={e=>setCompany({...company,legalName:e.target.value})}/></label><label>{t('email')}<input value={company.email||''} onChange={e=>setCompany({...company,email:e.target.value})}/></label><label>{t('phone')}<input value={company.phone||''} onChange={e=>setCompany({...company,phone:e.target.value})}/></label><label>{t('website')}<input value={company.website||''} onChange={e=>setCompany({...company,website:e.target.value})}/></label><label>{t('tax')}<input value={company.taxNumber||''} onChange={e=>setCompany({...company,taxNumber:e.target.value})}/></label><label className="full">{t('address')}<textarea rows={3} value={company.address||''} onChange={e=>setCompany({...company,address:e.target.value})}/></label></div></div><div className="panel"><h3>{t('branding')}</h3><p className="muted">{t('brandingHelp')}</p><div className="sa-branding-grid"><div><b>{t('logo')}</b><MediaChooser req={req} selected={branding.logoUrl||''} onChange={(v:string)=>setBranding({...branding,logoUrl:v})} label={t('choose')}/></div><div><b>{t('icon')}</b><MediaChooser req={req} selected={branding.iconUrl||''} onChange={(v:string)=>setBranding({...branding,iconUrl:v})} label={t('choose')}/></div><div><b>{t('whiteLogo')}</b><MediaChooser req={req} selected={branding.whiteLogoUrl||''} onChange={(v:string)=>setBranding({...branding,whiteLogoUrl:v})} label={t('choose')}/></div><div><b>{t('whiteIcon')}</b><MediaChooser req={req} selected={branding.whiteIconUrl||''} onChange={(v:string)=>setBranding({...branding,whiteIconUrl:v})} label={t('choose')}/></div></div></div><div className="panel"><h3>{saText('deep.final3.091')}</h3><p className="muted">{saText('deep.final3.092')}</p><div className="form-grid">{(['google','facebook'] as const).map(provider=><div className="full" key={provider}><h4 style={{textTransform:'capitalize'}}>{provider}</h4><label><input type="checkbox" checked={socialAuth.providers?.[provider]?.enabled!==false} onChange={e=>setSocialAuth((x:any)=>({...x,providers:{...x.providers,[provider]:{...x.providers?.[provider],enabled:e.target.checked}}}))}/> Aktif</label><label>Client ID<input value={socialAuth.providers?.[provider]?.clientId||''} onChange={e=>setSocialAuth((x:any)=>({...x,providers:{...x.providers,[provider]:{...x.providers?.[provider],clientId:e.target.value}}}))}/></label><label>Client Secret<input type="password" placeholder={socialAuth.providers?.[provider]?.secretConfigured?saText('deep.final3.093'):'Client secret'} value={socialAuth.providers?.[provider]?.clientSecret||''} onChange={e=>setSocialAuth((x:any)=>({...x,providers:{...x.providers,[provider]:{...x.providers?.[provider],clientSecret:e.target.value}}}))}/></label></div>)}</div></div><div className="panel"><div className="toolbar"><div><h3>{t('languages')}</h3><p className="muted">{t('languageHelp')}</p></div><button className="btn secondary" onClick={()=>setLocales(x=>[...x,{locale:'',label:'',isActive:true,isDefault:false,sortOrder:x.length}])}>{t('addLanguage')}</button></div><div className="sa-settings-rows">{locales.map((l:any,i:number)=><div className="sa-settings-row" key={i}><input placeholder="tr-TR" value={l.locale||''} onChange={e=>upd(setLocales,i,'locale',e.target.value)}/><input placeholder={saText('deep.final3.094')} value={l.label||''} onChange={e=>upd(setLocales,i,'label',e.target.value)}/><label className="sa-catalog-switch"><input type="checkbox" role="switch" aria-label="Aktif/Pasif" checked={l.isActive!==false} disabled={!!l.isDefault} onChange={e=>upd(setLocales,i,'isActive',e.target.checked)}/> {t('active')}</label><label><input type="radio" name="defaultLocale" checked={!!l.isDefault} onChange={()=>setLocales(x=>x.map((r,j)=>({...r,isDefault:j===i,isActive:j===i?true:r.isActive})))}/> {t('default')}</label><button className="btn secondary" disabled={!!l.isDefault} onClick={()=>setLocales(x=>x.filter((_,j)=>j!==i))}>{t('delete')}</button></div>)}</div></div><div className="panel"><div className="toolbar"><div><h3>{t('currencies')}</h3><p className="muted">{t('currencyHelp')}</p></div><button className="btn secondary" onClick={()=>setCurrencies(x=>[...x,{code:'',name:'',symbol:'',isActive:true,isDefault:false,sortOrder:x.length}])}>{t('addCurrency')}</button></div><div className="sa-settings-rows">{currencies.map((c:any,i:number)=><div className="sa-settings-row currency" key={i}><input placeholder="TRY" value={c.code||''} onChange={e=>upd(setCurrencies,i,'code',e.target.value.toUpperCase())}/><input placeholder={saText('deep.final3.095')} value={c.name||''} onChange={e=>upd(setCurrencies,i,'name',e.target.value)}/><input placeholder="₺" value={c.symbol||''} onChange={e=>upd(setCurrencies,i,'symbol',e.target.value)}/><label className="sa-catalog-switch"><input type="checkbox" role="switch" aria-label="Aktif/Pasif" checked={c.isActive!==false} disabled={!!c.isDefault} onChange={e=>upd(setCurrencies,i,'isActive',e.target.checked)}/> {t('active')}</label><label><input type="radio" name="defaultCurrency" checked={!!c.isDefault} onChange={()=>setCurrencies(x=>x.map((r,j)=>({...r,isDefault:j===i,isActive:j===i?true:r.isActive})))}/> {t('default')}</label><button className="btn secondary" disabled={!!c.isDefault} onClick={()=>setCurrencies(x=>x.filter((_,j)=>j!==i))}>{t('delete')}</button></div>)}</div></div>{msg&&<div className="success">{msg}</div>}{err&&<div className="error">{err}</div>}<div className="panel sa-save-row"><button className="btn" disabled={busy} onClick={()=>void save()}>{busy?t('saving'):t('save')}</button></div></>
}

function TeamControl({rows,req,reload}:any){const[editing,setEditing]=useState<any>(null);return <><div className="panel sa-page-head"><div><h2>Ekip</h2><p className="muted">{saText('deep.final3.096')}</p></div><button className="btn" onClick={()=>setEditing({})}>{saText('deep.final3.097')}</button></div><div className="panel"><Table rows={rows} cols={[["name","Ad"],["contactEmail","İletişim e-postası"],["phone","Telefon"],["roleLabel","Yetki"],["isRepresentative","Temsilci"],["isActive","Aktif"]]}/>{rows.map((x:any)=><button key={x.id} className="btn secondary sa-inline-edit" onClick={()=>setEditing(x)}>{saText('deep.final3.098')}{x.email}</button>)}</div>{editing&&<TeamModal row={editing} req={req} onClose={()=>setEditing(null)} onSaved={async()=>{setEditing(null);await reload()}}/>}</>}
function TeamModal({row,req,onClose,onSaved}:any){const perms=['dashboard','settings','memberships','plans','themes','apps','domains','currency','support','team'];const[form,setForm]=useState<any>({name:row.name||'',email:row.email||'',password:'',isActive:row.isActive!==false,permissions:row.permissions||perms,photoUrl:row.photoUrl||'',phone:row.phone||'',contactEmail:row.contactEmail||row.email||'',isRepresentative:!!row.isRepresentative}),[busy,setBusy]=useState(false),[err,setErr]=useState('');function toggle(p:string){setForm((x:any)=>({...x,permissions:x.permissions.includes(p)?x.permissions.filter((z:string)=>z!==p):[...x.permissions,p]}))}async function save(){setBusy(true);try{await req(row.id?'/superadmin/team/'+row.id:'/superadmin/team',{method:row.id?'PATCH':'POST',body:JSON.stringify(form)});onSaved()}catch(e:any){setErr(e.message)}finally{setBusy(false)}}return <Modal title={row.id?saText('deep.final3.099'):saText('deep.final3.097')} onClose={onClose}>{err&&<div className="error">{err}</div>}<div className="form-grid"><div className="full"><b>{saText('deep.final3.100')}</b><MediaChooser req={req} selected={form.photoUrl} onChange={(v:string)=>setForm({...form,photoUrl:v})}/></div><label>Ad<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>{saText('deep.final3.101')}<input value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Telefon<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>{saText('deep.final3.102')}<input value={form.contactEmail} onChange={e=>setForm({...form,contactEmail:e.target.value})}/></label><label>{saText('deep.final3.103')}<input type="password" placeholder={row.id?saText('deep.final3.104'):''} value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label><label>Durum<select value={String(form.isActive)} onChange={e=>setForm({...form,isActive:e.target.value==='true'})}><option value="true">Aktif</option><option value="false">Pasif</option></select></label><label className="full feature-check"><input type="checkbox" checked={form.isRepresentative} onChange={e=>setForm({...form,isRepresentative:e.target.checked})}/> {saText('deep.final3.105')}</label><div className="full"><b>Yetkiler</b><div className="feature-grid">{perms.map(p=><label className="feature-check" key={p}><input type="checkbox" checked={form.permissions.includes(p)} onChange={()=>toggle(p)}/>{p}</label>)}</div></div></div><ModalActions onClose={onClose} onSave={save} busy={busy}/></Modal>}

function ReservedSubdomainControl({rows,req,reload}:any){return <div className="panel"><div className="toolbar"><h3>{saText('deep.final3.106')}</h3></div><Table rows={rows} cols={[["value","Alt alan adı"],["reason","Açıklama"],["isActive","Aktif"]]}/></div>}
function CurrencyControl({data,req,reload}:any){const rows=Array.isArray(data?.rates)?data.rates:[];const[busy,setBusy]=useState(false);return <><div className="panel sa-page-head"><div><h3>{saText('deep.final3.002')}</h3><p className="muted">{saText('deep.final3.107')}</p></div><button className="btn" disabled={busy} onClick={async()=>{setBusy(true);try{await req('/superadmin/currency-rates/refresh',{method:'POST',body:'{}'});await reload()}finally{setBusy(false)}}}>{busy?saText('deep.final3.108'):saText('deep.final3.109')}</button></div><div className="panel"><div className="muted mb-3">Kaynak: {data?.source||'-'} {saText('deep.final3.110')}{data?.updatedAt?new Date(data.updatedAt).toLocaleString('tr-TR'):'-'}</div><Table rows={rows} cols={[["code","Kod"],["name","Tür"],["valueInTry","TRY karşılığı"],["kind","Tip"]]}/></div></>}

function SectorControl({rows,req,reload}:any){const locales=[{locale:'tr',label:'Türkçe'},{locale:'en',label:'English'},{locale:'de',label:'Deutsch'},{locale:'ru',label:'Русский'}];const[items,setItems]=useState<any[]>(Array.isArray(rows)?rows:[]),[busy,setBusy]=useState(false),[err,setErr]=useState('');useEffect(()=>setItems(Array.isArray(rows)?rows:[]),[rows]);function add(){setItems(x=>[...x,{id:`sector-${Date.now()}`,translations:{tr:{name:'Yeni sektör',description:''},en:{name:'',description:''},de:{name:'',description:''},ru:{name:'',description:''}},isActive:true,sortOrder:x.length}])}async function save(){setBusy(true);setErr('');try{await req('/superadmin/store-sectors',{method:'PATCH',body:JSON.stringify({sectors:items})});await reload()}catch(e:any){setErr(e.message)}finally{setBusy(false)}}return <div className="panel"><div className="toolbar"><div><h3>{saText('deep.final3.111')}</h3><p className="muted">{saText('deep.final3.112')}</p></div><button className="btn secondary" onClick={add}>{saText('deep.final3.113')}</button></div>{err&&<div className="error">{err}</div>}<div className="sa-category-list">{items.map((g:any,i:number)=><div className="sa-category-row" key={g.id}><div className="sa-category-meta"><label>Kod<input value={g.id} onChange={e=>setItems(x=>x.map((r,j)=>j===i?{...r,id:e.target.value}:r))}/></label><label>Durum<select value={String(g.isActive!==false)} onChange={e=>setItems(x=>x.map((r,j)=>j===i?{...r,isActive:e.target.value==='true'}:r))}><option value="true">Aktif</option><option value="false">Pasif</option></select></label><label>{saText('deep.final3.032')}<input type="number" value={g.sortOrder??i} onChange={e=>setItems(x=>x.map((r,j)=>j===i?{...r,sortOrder:Number(e.target.value||0)}:r))}/></label></div><TranslationEditor locales={locales} value={g.translations||{}} onChange={(v:any)=>setItems(x=>x.map((r,j)=>j===i?{...r,translations:v}:r))}/><button className="btn danger" onClick={()=>setItems(x=>x.filter((_,j)=>j!==i))}>Sil</button></div>)}</div><div className="sa-save-row"><button className="btn" disabled={busy} onClick={()=>void save()}>{busy?'Kaydediliyor…':saText('deep.final3.114')}</button></div></div>}
function Modal({title,subtitle,onClose,wide=false,children}:any){return <div className="sa-modal-backdrop"><div className={'sa-modal '+(wide?'sa-modal-wide':'')}><div className="sa-modal-head"><div><h2>{title}</h2>{subtitle&&<p className="muted">{subtitle}</p>}</div><button className="btn secondary" onClick={onClose}>Kapat</button></div>{children}</div></div>}
function ModalActions({onClose,onSave,busy}:any){return <div className="sa-modal-actions"><button className="btn secondary" onClick={onClose}>{saText('deep.final3.117')}</button><button className="btn" disabled={busy} onClick={()=>void onSave()}>{busy?'Kaydediliyor…':'Kaydet'}</button></div>}
function get(o:any,path:string){return path.split('.').reduce((a,k)=>Array.isArray(a)&&/^\d+$/.test(k)?a[Number(k)]:a?.[k],o)}
function Table({rows,cols}:{rows:any[],cols:[string,string][]}){rows=Array.isArray(rows)?rows:[];return <div className="table-scroll"><table><thead><tr>{cols.map(c=><th key={c[0]}>{c[1]}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.id||i}>{cols.map(c=>{let v=get(r,c[0]);if(c[0].includes('At')&&v)v=new Date(v).toLocaleString('tr-TR');if(typeof v==='boolean')v=v?'Evet':'Hayır';return <td key={c[0]}>{String(v??'-')}</td>})}</tr>)}</tbody></table></div>}


/** Read-only until the audited approve/restore workflow is implemented. */
function DeletionRequestsControl({data}: {data:any}) {
  const rows=Array.isArray(data?.items)?data.items:[];
  const phases:Record<string,string>={AWAITING_EMAIL_CONFIRMATION:'E-posta onayı bekleniyor',WAITING_PERIOD:'15 günlük bekleme',AWAITING_SUPERADMIN_REVIEW:'Super Admin incelemesi'};
  return <div className="panel">
    <h3>Mağaza Silme Talepleri</h3>
    <p className="muted">Bu ekran inceleme amaçlıdır. Finansal sayılar yalnızca ön kontroldür; ödeme ihtilafları ve hukuki yükümlülükler ayrıca incelenmelidir. Fiziksel veri silme ve mağazayı yeniden etkinleştirme bu sürümde yapılmaz.</p>
    <div className="table-responsive"><table className="table"><thead><tr><th>Mağaza</th><th>Durum</th><th>Talep tarihi</th><th>Planlanan tarih</th><th>Kalan süre</th><th>İnceleme aşaması</th><th>Finansal kontroller</th></tr></thead>
    <tbody>{rows.map((row:any)=><tr key={row.id}>
      <td><strong>{row.name||'-'}</strong><div className="muted">{row.publicSlug||'-'}</div></td>
      <td>{row.status||'-'}</td>
      <td>{row.deletionRequestedAt?new Date(row.deletionRequestedAt).toLocaleString('tr-TR'):'-'}</td>
      <td>{row.deletionScheduledAt?new Date(row.deletionScheduledAt).toLocaleString('tr-TR'):'-'}</td>
      <td>{row.remainingDays===null||row.remainingDays===undefined?'-':row.remainingDays===0?'Süre doldu':`${row.remainingDays} gün`}</td>
      <td>{phases[row.phase]||row.phase||'-'}</td>
      <td>{row.blockers ? <span>{row.hasFinancialBlockers?'Engel var':'Açık kayıt yok'} · Sipariş: {row.blockers.activeOrders} · İade: {row.blockers.activeReturns} · Ödenmemiş fatura: {row.blockers.unpaidInvoices}</span> : 'Kontrol edilmedi'}</td>
    </tr>)}{rows.length===0&&<tr><td colSpan={7} className="muted">Henüz silme talebi bulunmuyor.</td></tr>}</tbody></table></div>
  </div>;
}
